/* ================================================================
   IdeaForum 404 — styles
   ================================================================ */

*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --red: #EB0028;
  --red-hover: #C70022;
  --dark: #121212;
  --body: #444444;
  --muted: #696969;
  --link: #777777;
  --light-gray: #F4F4F5;
  --border: #E4E4E7;
  --white: #FFFFFF;
  --ghost: #F0F0F1;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.04), 0 1px 3px rgba(0,0,0,0.06);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.06), 0 1px 3px rgba(0,0,0,0.04);
  --shadow-lg: 0 8px 30px rgba(0,0,0,0.08), 0 2px 6px rgba(0,0,0,0.04);
  --transition: 180ms ease;
  --font: 'DM Sans', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --mono: 'DM Mono', ui-monospace, 'SFMono-Regular', Consolas, monospace;
}

html {
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.6;
  color: var(--body);
  background: var(--white);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

body {
  min-height: 100vh;
  overflow-x: hidden;
}

body.modal-open {
  overflow: hidden;
}

/* ---- Skip link ---- */
.skip-link {
  position: absolute;
  top: -100%;
  left: 16px;
  z-index: 100;
  padding: 8px 16px;
  background: var(--dark);
  color: var(--white);
  font-size: 0.875rem;
  border-radius: var(--radius-sm);
  text-decoration: none;
}
.skip-link:focus {
  top: 16px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

/* ================================================================
   PAGE LAYOUT
   ================================================================ */
.page {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  min-height: 100vh;
  padding: 0 24px;
  overflow: hidden;
}

/* Ghost 404 background */
.ghost-404 {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -55%);
  font-family: var(--font);
  font-weight: 700;
  font-size: clamp(280px, 42vw, 520px);
  line-height: 1;
  letter-spacing: -0.04em;
  color: transparent;
  -webkit-text-stroke: 1.5px var(--border);
  user-select: none;
  pointer-events: none;
  opacity: 0.55;
  z-index: 0;
}

/* ================================================================
   TOP BAR
   ================================================================ */
.topbar {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  max-width: 980px;
  padding: 28px 0;
}

.brand-mini {
  display: flex;
  align-items: center;
  gap: 8px;
  text-decoration: none;
}
.brand-mini__mark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: 6px;
  background: var(--red);
  color: var(--white);
  font-weight: 700;
  font-size: 16px;
  line-height: 1;
}
.brand-mini__name {
  font-weight: 600;
  font-size: 0.9375rem;
  color: var(--dark);
  letter-spacing: -0.01em;
}
.topbar__nav {
  display: flex;
  gap: 24px;
}
.topbar__nav a {
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--muted);
  text-decoration: none;
  letter-spacing: 0.005em;
  transition: color var(--transition);
}
.topbar__nav a:hover {
  color: var(--dark);
}

/* ================================================================
   HERO CONTENT
   ================================================================ */
.hero {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
