    align-items: stretch;
    gap: 16px;
    padding: 16px 20px;
  }
  .cookie__actions {
    justify-content: stretch;
  }
  .cookie__actions .btn {
    flex: 1;
  }
  .footer {
    flex-direction: column;
    gap: 12px;
    text-align: center;
    padding: 20px 0;
  }
  .ghost-404 {
    font-size: 220px;
  }
}

/* Mobile */
@media (max-width: 480px) {
  .page {
    padding: 0 16px;
  }
  .hero {
    padding: 16px 0 40px;
  }
  .brand {
    margin-bottom: 28px;
  }
  .brand__word {
    font-size: 38px;
  }
  .brand__missing {
    width: 26px;
    height: 38px;
  }
  .headline {
    font-size: 1.375rem;
  }
  .lede {
    font-size: 0.875rem;
    margin-bottom: 24px;
  }
  .search input {
    height: 48px;
    font-size: 0.875rem;
    padding: 0 48px 0 16px;
  }
  .search__btn {
    width: 36px;
    height: 36px;
  }
  .search {
    margin-bottom: 20px;
  }
  .error-code {
    font-size: 0.75rem;
    padding: 6px 14px;
    margin-bottom: 20px;
  }
  .rule {
    margin-bottom: 20px;
  }
  .modal__panel {
    padding: 24px 20px;
  }
  .footer__links {
    gap: 14px;
    flex-wrap: wrap;
    justify-content: center;
  }
  .ghost-404 {
    font-size: 160px;
