\n  align-items: center;\n  text-align: center;\n  width: 100%;\n  max-width: 560px;\n  flex: 1;\n  justify-content: center;\n  padding: 32px 0 64px;\n}\n\n/* Brand wordmark */\n.brand {\n  display: inline-flex;\n  align-items: baseline;\n  text-decoration: none;\n  margin-bottom: 40px;\n}\n.brand__word {\n  font-size: clamp(42px, 7vw, 68px);\n  font-weight: 700;\n  color: var(--red);\n  line-height: 1;\n  letter-spacing: -0.03em;\n}\n.brand__missing {\n  display: inline-flex;\n  align-items: flex-end;\n  width: clamp(28px, 4.5vw, 44px);\n  height: clamp(42px, 7vw, 68px);\n  margin: 0 -2px;\n}\n.brand__missing svg {\n  width: 100%;\n  height: 100%;\n}\n\n.eyebrow {\n  font-size: 0.6875rem;\n  font-weight: 600;\n  letter-spacing: 0.1em;\n  text-transform: uppercase;\n  color: var(--red);\n  margin-bottom: 12px;\n}\n\n.headline {\n  font-family: var(--font);\n  font-weight: 600;\n  font-size: clamp(1.75rem, 4.5vw, 2.25rem);\n  line-height: 1.2;\n  letter-spacing: -0.025em;\n  color: var(--dark);\n  margin-bottom: 8px;\n}\n\n.lede {\n  font-size: 0.9375rem;\n  color: var(--muted);\n  margin-bottom: 32px;\n  line-height: 1.5;\n}\n\n/* ================================================================\n   SEARCH\n   ================================================================ */\n.search {\n  position: relative;\n  width: 100%;\n  max-width: 460px;\n  margin-bottom: 28px;\n}\n.search input {\n  width: 100%;\n  height: 52px;\n  padding: 0 52px 0 20px;\n  font-family: var(--font);\n  font-size: 0.9375rem;\n  color: var(--dark);\n  background: var(--white);\n  border: 1.5px solid var(--border);\n  border-radius: var(--radius-md);\n  outline: none;\n  transition: border-color var(--transition), box-shadow var(--transition);\n}\n.search input::placeholder {\n  color: #A1A1AA;\n}\n.search input:focus {\n  border-color: var(--red);\n  box-shadow: 0 0 0 3px rgba(235,0,40,0.08);\n}\n.search__btn {\n  position: absolute;\n  right: 6px;\n  top: 50%;\n  transform: translateY(-50%)