3	(function () {
4	  "use strict";
5	
6	  /* ---- Year ---- */
7	  var yearEl = document.getElementById("year");
8	  if (yearEl) yearEl.textContent = new Date().getFullYear().toString();
9	
10	  /* ---- Search ---- */
11	  window.handleSearch = function (e) {
12	    e.preventDefault();
13	    var q = document.getElementById("q").value.trim();
14	    if (q) {
15	      window.location.href = "https://www.ideaforum.com/search?q=" + encodeURIComponent(q);
16	    }
17	    return false;
18	  };
