20	  /* ---- Cookie banner ---- */
21	  var banner = document.getElementById("cookie-banner");
22	  var acceptBtn = document.getElementById("accept-all");
23	  var openPrefsBtn = document.getElementById("open-prefs");
24	  var savedConsent = false;
25	
26	  try {
27	    savedConsent = localStorage.getItem("ideaforum_cookie_consent") === "1";
28	  } catch (_) {}
29	
30	  if (!savedConsent) {
31	    setTimeout(function () {
32	      banner.classList.add("visible");
33	    }, 800);
34	  }
35	
36	  function hideBanner() {
37	    banner.classList.remove("visible");
38	    banner.classList.add("hidden");
39	    try {
40	      localStorage.setItem("ideaforum_cookie_consent", "1");
41	    } catch (_) {}
42	  }
43	
44	  acceptBtn.addEventListener("click", hideBanner);
45	
46	  /* ---- Preferences modal ---- */
47	  var modal = document.getElementById("prefs");
48	  var saveBtn = document.getElementById("save-prefs");
49	  var closeBtns = modal.querySelectorAll("[data-close]");
50	  var lastFocused = null;
51	
52	  function openModal() {
53	    lastFocused = document.activeElement;
54	    modal.classList.add("open");
55	    modal.setAttribute("aria-hidden", "false");
56	    document.body.classList.add("modal-open");
57	    var firstFocusable = modal.querySelector("button, [href], input, select, textarea, [tabindex]:not([tabindex='-1'])");
58	    if (firstFocusable) firstFocusable.focus();
59	  }
60	
61	  function closeModal() {
62	    modal.classList.remove("open");
63	    modal.setAttribute("aria-hidden", "true");
64	    document.body.classList.remove("modal-open");
65	    if (lastFocused) lastFocused.focus();
66	  }
67	
68	  openPrefsBtn.addEventListener("click", function () {
69	    openModal();
70	  });
71	
72	  closeBtns.forEach(function (btn) {
73	    btn.addEventListener("click", closeModal);
74	  });
75	
76	  saveBtn.addEventListener("click", function () {
77	    hideBanner();
78	    closeModal();
79	  });
80	
81	  document.addEventListener("keydown", function (e) {
82	    if (e.key === "Escape" && modal.classList.contains("open")) {
83	      closeModal();
84	    }
85	  });
86	
87	  /* Trap focus inside modal */
88	  modal.addEventListener("keydown", function (e) {
89	    if (e.key !== "Tab") return;
90	    var focusable = modal.querySelectorAll(
91	      'button:not([disabled]), [href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])'
92	    );
93	    if (!focusable.length) return;
94	    var first = focusable[0];
95	    var last = focusable[focusable.length - 1];
96	    if (e.shiftKey) {
97	      if (document.activeElement === first) {
98	        e.preventDefault();
99	        last.focus();
100	      }
101	    } else {
102	      if (document.activeElement === last) {
103	        e.preventDefault();
104	        first.focus();
105	      }
106	    }
107	  });
108	
109	  /* Update toggle labels when toggled */
110	  var toggles = document.querySelectorAll(".toggle:not(.toggle--locked) input");
111	  toggles.forEach(function (input) {
112	    input.addEventListener("change", function () {
113	      var label = this.closest(".toggle").querySelector(".toggle__label");
114	      if (label) label.textContent = this.checked ? "On" : "Off";
115	    });
116	  });
